        "thresholds": "not_applicable",
        "concepts": "correct",
        "source_attribution": "not_applicable",
        "effectivity": "not_applicable"
      }
    }
  ],
  "unit_judgments": [
    {
      "unit_id": "U0000",
      "claim_ids": ["C0000"],
      "quotes": [
        "(c)(1) Except as provided in paragraph (c)(2) of this section and in § 825.801 containing the special hours of service requirement for airline flight crew employees, whether an employee has worked the minimum 1,250 hours of service is determined according to the principles established under the Fair Labor Standards Act (FLSA) for determining compensable hours of work.",
        "Any accurate accounting of actual hours worked under FLSA's principles may be used."
      ],
      "rationale": "Unit U0000 is only partially covered by C0000 because C0000's explicit meaning fields (summary and scope_text) omit the governing exceptions for paragraph (c)(2) and § 825.801, and the summary omits the purpose of establishing the 1,250 hours of service threshold.",
      "status": "partial"
    }
  ]
}
